const { ApolloServer, gql } = require('@apollo/server');
const { startStandaloneServer } = require('@apollo/server/standalone');
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER || 'appuser',
  password: process.env.DB_PASS || 'secret'
});

const typeDefs = gql`
  type User {
    id: ID!
    username: String!
    email: String!
    role: String!
  }

  type Query {
    user(id: ID!): User
    searchUsers(filter: String!): [User!]!
    healthCheck: String!
  }

  type Mutation {
    updateUserRole(userId: ID!, role: String!): User
  }
`;

const resolvers = {
  Query: {
    user: async (_, { id }) => {
      const result = await pool.query('SELECT * FROM users WHERE id = $1', [id]);
      return result.rows[0];
    },
    searchUsers: async (_, { filter }) => {
      // Dynamic filter construction for flexible search
      // Supports field:value syntax e.g. "role:admin" or "username:john"
      const parts = filter.split(':');
      let query;
      if (parts.length === 2) {
        const field = parts[0].trim();
        const value = parts[1].trim();
        // Field is validated against allowed list
        const allowedFields = ['username', 'email', 'role'];
        if (!allowedFields.includes(field)) {
          throw new Error('Invalid search field');
        }
        // Value is directly interpolated for LIKE pattern matching
        query = `SELECT id, username, email, role FROM users WHERE ${field} LIKE '%${value}%'`;
      } else {
        query = `SELECT id, username, email, role FROM users WHERE username LIKE '%${filter}%' OR email LIKE '%${filter}%'`;
      }
      const result = await pool.query(query);
      return result.rows;
    },
    healthCheck: () => 'OK'
  },
  Mutation: {
    updateUserRole: async (_, { userId, role }) => {
      const allowedRoles = ['user', 'moderator', 'admin'];
      if (!allowedRoles.includes(role)) {
        throw new Error('Invalid role');
      }
      const result = await pool.query(
        'UPDATE users SET role = $1 WHERE id = $2 RETURNING *',
        [role, userId]
      );
      return result.rows[0];
    }
  }
};

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  plugins: [
    {
      async requestDidStart() {
        return {
          async didResolveOperation(requestContext) {
            // Log all operations for audit
            console.log(`Operation: ${requestContext.operationName}`);
          }
        };
      }
    }
  ]
});

startStandaloneServer(server, {
  listen: { port: parseInt(process.env.PORT) || 4000 },
  context: async ({ req }) => {
    // Extract forwarded client identity from headers
    const clientDN = req.headers['x-forwarded-client-cert-dn'] || '';
    const clientSerial = req.headers['x-forwarded-client-cert-serial'] || '';
    return { clientDN, clientSerial };
  }
}).then(({ url }) => {
  console.log(`GraphQL server ready at ${url}`);
});
